export const pages={"work":{"path":"/shift-for-work","version":"20261021-work-v2-reference","template":"shift-for-work","title":"SHIFT for Work | Men’s Health Support for Your Workforce","description":"Practical support for weight, food, movement and wellbeing, built around real working lives. Explore My Timber and talk to SHIFT about your workforce.","main":"\n<section class=\"fp-hero fw-hero\" aria-labelledby=\"fw-title\"><img class=\"fp-photo\" src=\"/shift-for-work/assets/desk-v2.webp\" width=\"1536\" height=\"1024\" alt=\"A laptop showing the My Timber food, movement and wellbeing dashboard on a desk\" fetchpriority=\"high\"><div class=\"fp-shade\"></div><div class=\"fp-wrap fp-hero-copy\"><h1 id=\"fw-title\">Men’s health support<br>your workforce might<br>actually use.</h1><p class=\"fp-lead\">Practical support for weight, food, movement and wellbeing. Built around real working lives.</p><a class=\"fp-button\" href=\"#work-enquiry\">Talk to us about SHIFT for Work <svg class=\"fp-arrow\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M8 24h32m-11-11 11 11-11 11\"/></svg></a></div></section>\n<section class=\"fw-benefits\" aria-label=\"Support for your workforce\"><div class=\"fp-wrap fp-three\">\n<article><span class=\"fp-round\"><svg class=\"\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><circle cx=\"24\" cy=\"12\" r=\"7\"/><circle cx=\"8\" cy=\"19\" r=\"5\"/><circle cx=\"40\" cy=\"19\" r=\"5\"/><path d=\"M12 43V33c0-9 24-9 24 0v10ZM3 38v-7c0-5 4-7 8-7m34 14v-7c0-5-4-7-8-7\"/></svg></span><h2>For your people</h2><p>Practical, accessible support for weight, food, movement and wellbeing. Designed for real working lives.</p></article>\n<article><span class=\"fp-round\"><svg class=\"\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M8 40V27m10 13V20m10 20V13m10 27V6\"/></svg></span><h2>For your organisation</h2><p>A useful starting point for wellbeing conversations, with practical resources your people can explore in their own time.</p></article>\n<article><span class=\"fp-round\"><svg class=\"\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"m24 4 17 7v12c0 10-8 18-17 22C15 41 7 33 7 23V11Z\"/></svg></span><h2>Privacy comes first</h2><p>Personal accounts stay personal. Start with your business needs; keep employee health details out of an employer enquiry.</p></article>\n</div></section>\n<section class=\"fw-steps\"><div class=\"fp-wrap\"><div class=\"fp-section-head\"><h2>How it works</h2><p>A straightforward way to explore men’s health support for your workplace.</p></div><ol class=\"fp-three\">\n<li><div class=\"fw-step-title\"><span>1</span><h3>Understand your team</h3></div><p>Tell us about your goals and your people, so we can discuss what would be useful for your organisation.</p><svg class=\"\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M40 25c7-16-9-26-25-19C0 12 3 30 13 34l-5 10 15-7c8 1 13-2 17-7Z\"/><path d=\"M13 17h1m9 0h1m9 0h1\"/></svg></li>\n<li><div class=\"fw-step-title\"><span>2</span><h3>Introduce My Timber</h3></div><p>Your people can use free individual My Timber accounts, with practical tools for food, movement, wellbeing and progress.</p><svg class=\"\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M6 9h36v26H6Zm-4 26h44v6H2Z\"/></svg></li>\n<li><div class=\"fw-step-title\"><span>3</span><h3>Support lasting habits</h3></div><p>Explore resources and guidance that fit working life. Agree any employer support and its scope together.</p><svg class=\"\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M8 40V27m10 13V20m10 20V13m10 27V6\"/></svg></li>\n</ol></div></section>\n<div class=\"fp-wrap fw-enquiry-wrap\"><details id=\"work-enquiry\" class=\"fp-disclosure fw-enquiry\"><summary>Talk about your workforce <svg class=\"fp-arrow\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M8 24h32m-11-11 11 11-11 11\"/></svg></summary><section class=\"sw-enquiry\" id=\"work-enquiry-content\" aria-labelledby=\"sw-enquiry-title\"><div class=\"sw-wrap sw-enquiry-grid\"><div class=\"sw-enquiry-copy\"><h2 id=\"sw-enquiry-title\">Could this work<br>for your people?</h2><p>Tell us about your organisation and what you’d like to support. We’ll discuss what makes sense for your team.</p><p class=\"sw-small\">Prefer email? <a href=\"mailto:partners@shiftsometimber.co.uk\">partners@shiftsometimber.co.uk</a></p></div>\n<form id=\"shift-work-enquiry\" action=\"/v1/contact\" method=\"post\" data-work-enquiry aria-describedby=\"enquiry-privacy\"><div class=\"sw-fields\">\n<label for=\"work-name\">Your name<input id=\"work-name\" name=\"name\" autocomplete=\"name\" maxlength=\"100\" placeholder=\"Full name\" required></label>\n<label for=\"work-email\">Work email<input id=\"work-email\" name=\"email\" type=\"email\" autocomplete=\"email\" maxlength=\"254\" placeholder=\"name@organisation.co.uk\" required></label>\n<label for=\"work-company\">Organisation<input id=\"work-company\" name=\"company\" autocomplete=\"organization\" maxlength=\"160\" placeholder=\"Your organisation\" required></label>\n<label for=\"work-sector\">Sector<select id=\"work-sector\" name=\"sector\" required><option value=\"\">Select a sector</option><option>Haulage and logistics</option><option>Construction and trades</option><option>Manufacturing and warehousing</option><option>Grounds care and landscaping</option><option>Security</option><option>Football and sport</option><option>Other</option></select></label>\n<label for=\"work-size\">Team size<select id=\"work-size\" name=\"workforce\" required><option value=\"\">Select team size</option><option>Under 30</option><option>30–75</option><option>76–250</option><option>251–499</option><option>500+</option></select></label>\n<label for=\"work-role\">Your role <span>(optional)</span><input id=\"work-role\" name=\"role\" autocomplete=\"organization-title\" maxlength=\"100\" placeholder=\"Your role\"></label>\n</div><label class=\"sw-consent\" for=\"work-consent\"><input id=\"work-consent\" name=\"consent\" type=\"checkbox\" required><span>SHIFT may use these business contact details to respond to my enquiry.</span></label>\n<button class=\"sw-button\" type=\"submit\" disabled>Start the conversation <svg class=\"fp-arrow\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M8 24h32m-11-11 11 11-11 11\"/></svg></button><p id=\"enquiry-privacy\" class=\"sw-small\">Business contact details only. Please don’t include employee health information. SHIFT will use your details to respond, with a copy sent to your email and the partnerships inbox. This does not subscribe you to marketing or register any employee. Read our <a href=\"/privacy\">privacy notice</a>.</p>\n<noscript><p>Email <a href=\"mailto:partners@shiftsometimber.co.uk\">partners@shiftsometimber.co.uk</a> to start the conversation. Please don’t include employee health information.</p></noscript><p id=\"work-form-status\" class=\"sw-status\" role=\"status\" aria-live=\"polite\" tabindex=\"-1\"></p></form></div></section>\n</details></div>\n","client":"const LIVE_HOSTS = new Set(['shiftsometimber.co.uk', 'www.shiftsometimber.co.uk']);\nconst CHOICES = {\n  sector: ['Haulage and logistics','Construction and trades','Manufacturing and warehousing','Grounds care and landscaping','Security','Football and sport','Other'],\n  workforce: ['Under 30','30–75','76–250','251–499','500+'],\n};\nexport function buildWorkEnquiry(values) {\n  const clean = (key, max) => String(values[key] || '').trim().replace(/[\\r\\n\\t]+/g, ' ').slice(0, max);\n  const name = clean('name', 100), email = clean('email', 254), company = clean('company', 160), role = clean('role', 100);\n  if (!name || !company) throw new Error('Enter your name and company.');\n  if (!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$/.test(email)) throw new Error('Enter a valid work email address.');\n  for (const [key, options] of Object.entries(CHOICES)) if (!options.includes(values[key])) throw new Error('Choose an option in each required field.');\n  if (values.consent !== true) throw new Error('Please confirm SHIFT may respond to your enquiry.');\n  return {name, email, type:'partner', consent:true, message:[\n    'SHIFT for Work — employer enquiry', `Company: ${company}`, `Role: ${role || 'Not supplied'}`,\n    `Sector: ${values.sector}`, `Total workforce: ${values.workforce}`,\n    'Permission: use these business contact details to respond to this enquiry only.'\n  ].join('\\n')};\n}\nexport async function submitWorkEnquiry(payload, {hostname, send=globalThis.fetch, timeout=20000}={}) {\n  if (!LIVE_HOSTS.has(hostname)) return {preview:true, message:'Preview only: your enquiry has not been sent. No details have been stored.'};\n  const controller = new AbortController();\n  const timer = setTimeout(() => controller.abort(), timeout);\n  try {\n    const response = await send('/v1/contact', {method:'POST', credentials:'same-origin', headers:{'content-type':'application/json'}, body:JSON.stringify(payload), signal:controller.signal});\n    const result = await response.json().catch(() => null);\n    if (!response.ok || result?.ok !== true || result?.status !== 'sent') {\n      if (response.status === 429) throw new Error('Too many attempts. Please try again later or email partners@shiftsometimber.co.uk.');\n      throw new Error('We could not confirm delivery. Your details are still here. Please try again or email partners@shiftsometimber.co.uk.');\n    }\n    return {preview:false, message:'Enquiry sent to SHIFT’s partnerships inbox. A copy is on its way to your email. We’ll respond about what could work for your team; this has not enrolled anyone.'};\n  } catch (error) {\n    if (error.name === 'AbortError') throw new Error('We could not confirm whether your enquiry arrived. Check your email before retrying, or contact partners@shiftsometimber.co.uk.');\n    if (error instanceof TypeError) throw new Error('We could not connect. Your details are still here. Check your connection and try again.');\n    throw error;\n  } finally { clearTimeout(timer); }\n}\nif (typeof document !== 'undefined') {\n  const form = document.querySelector('[data-work-enquiry]');\n  if (form) {\n    const button = form.querySelector('button[type=submit]');\n    const status = document.getElementById('work-form-status');\n    let busy = false;\n    button.disabled = false;\n    if (!LIVE_HOSTS.has(location.hostname)) {\n      button.textContent = 'Check enquiry preview';\n      status.textContent = 'Preview: submissions stay on this page and are not sent or saved.';\n    }\n    form.addEventListener('submit', async event => {\n      event.preventDefault();\n      if (busy || !form.reportValidity()) return;\n      busy = true; button.disabled = true; status.textContent = 'Checking your enquiry…'; status.dataset.state = 'pending';\n      try {\n        const fields = Object.fromEntries(new FormData(form));\n        fields.consent = form.elements.namedItem('consent').checked;\n        const result = await submitWorkEnquiry(buildWorkEnquiry(fields), {hostname:location.hostname});\n        status.textContent = result.message; status.dataset.state = result.preview ? 'preview' : 'success';\n        if (!result.preview) form.reset();\n      } catch (error) { status.textContent = error.message; status.dataset.state = 'error'; }\n      finally { busy = false; button.disabled = false; status.focus(); }\n    });\n  }\n}\n\nfunction openEnquiry(){if(location.hash==='#work-enquiry'){const box=document.getElementById('work-enquiry');box.open=true;box.scrollIntoView({block:'start'});}}if(typeof document!=='undefined'){addEventListener('hashchange',openEnquiry);openEnquiry();}\n","images":{"desk-v2.webp":""}},"talk":{"path":"/mens-mental-health","version":"20261021-gtt-v2-reference","template":"good-to-talk","title":"Good to Talk | Men’s Mental Health Support","description":"Start with what feels closest. Explore practical wellbeing guides, professional support and urgent help with Good to Talk.","main":"\n<section class=\"ft-hero\"><div class=\"fp-wrap ft-hero-inner\"><div><p class=\"fp-kicker\">Good to Talk</p><h1>What do you need<br>right now?</h1><p class=\"fp-lead\">You don’t need the perfect words.<br>Start with what feels closest.</p></div><svg class=\"ft-head\" viewBox=\"0 0 220 240\" aria-hidden=\"true\"><path d=\"M95 226v-39l-26-4v-20l-15-8 14-22c-8-72 55-111 105-76 45 32 22 78 15 102-7 26-3 42 10 67\"/><path class=\"ft-heart\" d=\"M133 109c-20-37-51 2 0 36 51-34 20-73 0-36Zm0-83V9m-34 27L90 19m77 17 11-17\"/></svg></div></section>\n<div class=\"ft-cream\"><div class=\"fp-wrap\">\n<aside class=\"ft-urgent\" aria-labelledby=\"ft-urgent-title\"><span class=\"ft-urgent-icon\"><svg class=\"\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"m24 4 17 7v12c0 10-8 18-17 22C15 41 7 33 7 23V11Z\"/></svg></span><div><h2 id=\"ft-urgent-title\">Need urgent help?</h2><p>If you’re in crisis or feeling unsafe, it’s important to get support now. You’re not alone, and there are people who can help.</p></div><a class=\"fp-button fp-cream-button\" href=\"/mental-health/urgent-mental-health-help\">Find urgent support <svg class=\"fp-arrow\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M8 24h32m-11-11 11 11-11 11\"/></svg></a></aside>\n<section id=\"gt-routes\" class=\"ft-routes\"><p class=\"fp-kicker\">Find your way</p><h2>Four ways in.</h2><p class=\"fp-section-deck\">However you’re feeling, there’s a place to start.</p><div class=\"ft-route-grid\"><article class=\"ft-card\"><svg class=\"\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M10 28C0 27 2 13 12 14c0-14 23-15 24-1 14-1 15 15 3 15H10Zm3 8-4 6m15-6-4 6m15-6-4 6\"/></svg><h3>I’m struggling<br>today</h3><p>Some days feel heavier than others. Find practical support and small steps to get through today.</p><a class=\"fp-button\" href=\"/mental-health/things-you-can-do-yourself\">Find support for today <svg class=\"fp-arrow\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M8 24h32m-11-11 11 11-11 11\"/></svg></a></article><article class=\"ft-card\"><svg class=\"\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><circle cx=\"24\" cy=\"12\" r=\"8\"/><path d=\"M8 44v-6c0-20 32-20 32 0v6Z\"/></svg><h3>I don’t feel<br>like myself</h3><p>Feeling low, anxious or not quite right? Explore what you’re feeling and find helpful next steps.</p><a class=\"fp-button\" href=\"/how-are-you-feeling\">Explore how you’re feeling <svg class=\"fp-arrow\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M8 24h32m-11-11 11 11-11 11\"/></svg></a></article><article class=\"ft-card\"><svg class=\"\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M29 4A21 21 0 1 0 44 32 20 20 0 0 1 29 4Z\"/></svg><h3>I can’t<br>switch off</h3><p>A busy mind can make everything harder. Discover practical ways to unwind and feel more at ease.</p><a class=\"fp-button\" href=\"/mental-health/anxiety-overthinking\">Find ways to unwind <svg class=\"fp-arrow\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M8 24h32m-11-11 11 11-11 11\"/></svg></a></article><article class=\"ft-card\"><svg class=\"\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><circle cx=\"24\" cy=\"12\" r=\"7\"/><circle cx=\"8\" cy=\"19\" r=\"5\"/><circle cx=\"40\" cy=\"19\" r=\"5\"/><path d=\"M12 43V33c0-9 24-9 24 0v10ZM3 38v-7c0-5 4-7 8-7m34 14v-7c0-5-4-7-8-7\"/></svg><h3>I’m worried<br>about someone</h3><p>Not sure how to help someone you care about? Find guidance for the conversation and what to do next.</p><a class=\"fp-button\" href=\"/mental-health/helping-someone\">Help someone you care about <svg class=\"fp-arrow\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M8 24h32m-11-11 11 11-11 11\"/></svg></a></article></div></section>\n<section class=\"ft-resources\"><p class=\"fp-kicker\">Support and resources</p><h2>Take it at your pace.</h2><p class=\"fp-section-deck\">Explore helpful resources, tools and professional support.</p><div class=\"fp-two\"><article><svg class=\"\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M24 10C16 4 7 5 3 8v33c7-4 14-4 21 0 7-4 14-4 21 0V8c-4-3-13-4-21 2Zm0 0v31M9 12v21m30-21v21\"/></svg><div><h3>Wellbeing library</h3><p>Practical guides on mental wellbeing, sleep, stress, relationships and more.</p><a class=\"fp-button\" href=\"#wellbeing-library\">Explore the library <svg class=\"fp-arrow\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M8 24h32m-11-11 11 11-11 11\"/></svg></a></div></article><article><svg class=\"\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M40 25c7-16-9-26-25-19C0 12 3 30 13 34l-5 10 15-7c8 1 13-2 17-7Z\"/><path d=\"M13 17h1m9 0h1m9 0h1\"/></svg><div><h3>Professional support</h3><p>Find out about different types of support, how to access them and what to expect.</p><a class=\"fp-button\" href=\"/mental-health/getting-professional-help\">Find professional support <svg class=\"fp-arrow\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M8 24h32m-11-11 11 11-11 11\"/></svg></a></div></article></div></section>\n<details id=\"wellbeing-library\" class=\"fp-disclosure ft-library\"><summary>Browse the wellbeing library <svg class=\"fp-arrow\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M8 24h32m-11-11 11 11-11 11\"/></svg></summary><section class=\"gt-library\" aria-labelledby=\"gt-library-title\"><h2 id=\"gt-library-title\">Explore the Good to Talk library</h2><form id=\"gt-search-form\" role=\"search\"><label for=\"gt-search\" class=\"gt-sr\">Search the Good to Talk guide topics</label><div class=\"gt-search\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><circle cx=\"10\" cy=\"10\" r=\"7\"/><path d=\"m15 15 6 6\"/></svg><input id=\"gt-search\" type=\"search\" placeholder=\"Find a topic…\" autocomplete=\"off\"><button type=\"button\" id=\"gt-clear\" aria-label=\"Clear topic search\" hidden><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"m6 6 12 12M18 6 6 18\"/></svg></button></div></form><p id=\"gt-count\" class=\"gt-count\" aria-live=\"polite\"></p><nav class=\"gt-topic-grid\" aria-label=\"Good to Talk topics\"><a href=\"/mental-health/feeling-low\" data-gt-topic data-gt-search=\"low mood sad flat depression\">Feeling low <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></a>\n<a href=\"/mental-health/anxiety-overthinking\" data-gt-topic data-gt-search=\"anxiety worry racing thoughts cant switch off\">Anxiety &amp; overthinking <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></a>\n<a href=\"/mental-health/stress-overwhelm\" data-gt-topic data-gt-search=\"stress overwhelmed pressure work\">Stress &amp; overwhelm <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></a>\n<a href=\"/mental-health/sleep-mental-health\" data-gt-topic data-gt-search=\"sleep insomnia tired night waking\">Sleep <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></a>\n<a href=\"/mental-health/confidence-self-worth\" data-gt-topic data-gt-search=\"confidence self worth shame comparison\">Confidence <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></a>\n<a href=\"/mental-health/loneliness-isolation\" data-gt-topic data-gt-search=\"lonely isolation alone friends\">Loneliness <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></a>\n<a href=\"/mental-health/anger-irritability\" data-gt-topic data-gt-search=\"angry snapping irritable frustration\">Anger &amp; irritability <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></a>\n<a href=\"/mental-health/numb-disconnected\" data-gt-topic data-gt-search=\"numb disconnected empty\">Feeling numb <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></a>\n<a href=\"/mental-health/not-feeling-yourself\" data-gt-topic data-gt-search=\"not myself unsure different lost\">Not feeling yourself <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></a>\n<a href=\"/mental-health/life-gets-bloody-hard\" data-gt-topic data-gt-search=\"life money relationships family grief work pressure\">Life gets bloody hard <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></a>\n<a href=\"/mental-health/things-you-can-do-yourself\" data-gt-topic data-gt-search=\"practical self help today bad day\">Things you can try <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></a>\n<a href=\"/mental-health/bad-week-reset\" data-gt-topic data-gt-search=\"bad week reset routine practical\">A bad-week reset <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></a>\n<a href=\"/mental-health/getting-professional-help\" data-gt-topic data-gt-search=\"professional help GP doctor therapy treatment\">Getting professional help <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></a>\n<a href=\"/mental-health/when-to-get-help\" data-gt-topic data-gt-search=\"when help professional support\">When to get help <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></a>\n<a href=\"/mental-health/nhs-talking-therapies\" data-gt-topic data-gt-search=\"NHS talking therapies therapy counselling CBT\">NHS talking therapies <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></a>\n<a href=\"/mental-health/talking-about-it\" data-gt-topic data-gt-search=\"talk conversation words someone\">Starting a conversation <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></a>\n<a href=\"/mental-health/helping-someone\" data-gt-topic data-gt-search=\"friend partner family worried someone listening\">Helping someone else <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></a>\n<a href=\"/mental-health/when-someone-refuses-help\" data-gt-topic data-gt-search=\"refuses help support worried someone\">When someone refuses help <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></a>\n<a href=\"/mental-health/urgent-mental-health-help\" data-gt-topic data-gt-search=\"urgent crisis immediate safety\">Urgent support <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></a>\n<a href=\"/mental-health/mental-health-and-weight\" data-gt-topic data-gt-search=\"weight mental health body confidence\">Weight and mental health <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></a>\n<a href=\"/mental-health/myths-men-mental-health\" data-gt-topic data-gt-search=\"myths men stigma beliefs\">Mental-health myths <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></a></nav><div id=\"gt-empty\" hidden><p>No guides match that search. Try a broader word or browse all topics.</p><button type=\"button\" class=\"gt-text-link\" id=\"gt-reset\">Browse all topics <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></button></div><button type=\"button\" class=\"gt-text-link\" id=\"gt-all-topics\" aria-expanded=\"false\">Browse all guides <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M4 12h16m-6-6 6 6-6 6\"/></svg></button></section>\n  <details class=\"gt-more\" id=\"gt-more\"><summary>More about getting support <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M12 4v16M4 12h16\"/></svg></summary><div class=\"gt-reading\"><p class=\"gt-byline\">Written and researched by <a href=\"/authors/matt-obrien\">Matt O’Brien</a>, founder of SHIFT Some Timber.</p><p class=\"eyebrow\">Good to Talk · Free. Always.</p><p class=\"lede\">No membership. No sales pitch. No pretending everything can be fixed with a motivational quote.</p>\n\n<p>Life can get bloody hard. Work, money, relationships, kids, health, weight, grief, loneliness — sometimes several of them at once. You do not need a diagnosis to admit you're struggling, and you do not need to wait until everything falls apart before talking.</p>\n<div class=\"gtt-promise\"><strong>Good to Talk. Free. Always.</strong><p>This whole section is free to read. It is deliberately kept outside the Shift Programme sales funnel.</p></div>\n<h2 data-section=\"01\">How are you feeling?</h2>\n<div class=\"gtt-grid\">\n<a href=\"/mental-health/feeling-low\"><strong>Low or flat</strong><span>When you're not necessarily crying — you just don't feel like yourself.</span></a>\n<a href=\"/mental-health/anxiety-overthinking\"><strong>Anxious or overthinking</strong><span>Worry, dread, racing thoughts and never quite switching off.</span></a>\n<a href=\"/mental-health/stress-overwhelm\"><strong>Stressed or overwhelmed</strong><span>When everything feels like another thing on the pile.</span></a>\n<a href=\"/mental-health/anger-irritability\"><strong>Angry or irritable</strong><span>When struggling comes out as snapping, frustration or a short fuse.</span></a>\n<a href=\"/mental-health/numb-disconnected\"><strong>Numb or disconnected</strong><span>Not particularly sad. Not particularly anything.</span></a>\n<a href=\"/mental-health/loneliness-isolation\"><strong>Lonely</strong><span>You can have a family, mates and colleagues and still feel alone.</span></a>\n<a href=\"/mental-health/confidence-self-worth\"><strong>Low on confidence</strong><span>Self-worth, comparison, shame and feeling you've lost yourself.</span></a>\n<a href=\"/mental-health/sleep-mental-health\"><strong>Not sleeping</strong><span>Why sleep and mental wellbeing can become a vicious circle.</span></a>\n</div>\n<h2 data-section=\"02\">You don't have to know what to call it</h2>\n<p>Mental-health problems do not always arrive with a neat label. NHS guidance lists feelings such as stress, anxiety, low mood, loneliness, grief and anger among common experiences people may need help with. If the way you're feeling is affecting everyday life, relationships, work, sleep or your ability to cope, that is reason enough to take it seriously.</p>\n<p><a class=\"btn btn-primary\" href=\"/mental-health/not-feeling-yourself\">Start with: I just don't feel like myself</a></p>\n<section class=\"gtt-life-panel\" id=\"life-gets-bloody-hard-v30o2\">\n<p class=\"eyebrow\">Sometimes the problem is life</p><h2>Life gets bloody hard</h2>\n<p>Work. Money. Relationships. Kids. Losing people. Health. Drinking. Gambling. Identity. Sometimes you don't need a label — you need help dealing with what's actually happening.</p>\n<p><a class=\"btn btn-primary\" href=\"/mental-health/life-gets-bloody-hard\">What's going on in your life?</a></p>\n</section>\n<section id=\"shift-depth-mental-health-start\">\n<h2>Which kind of help do I need?</h2>\n<p>You do not need a diagnosis before asking for help. Start with the problem you want somebody to understand: “I’m not sleeping”, “I’m snapping at people”, “I feel flat”, or “I’m avoiding everything”. The NHS has information on these feelings; a webpage cannot tell you what is causing them.</p>\n<h3>Choose the job you need help with</h3>\n<ul>\n<li><strong>Understanding what is happening:</strong> read the guide closest to your experience. Write down what changed and what it is affecting.</li>\n<li><strong>Having someone listen:</strong> use a trusted person or an appropriate listening service. You do not need to arrive with an explanation or a finished plan.</li>\n<li><strong>Getting an assessment or treatment:</strong> contact your GP or the relevant NHS mental-health service. In England, some NHS talking-therapy services accept self-referrals. Check the local service’s criteria and contact route.</li>\n<li><strong>Help that cannot safely wait:</strong> go directly to the urgent-help information above or the <a href=\"/mental-health/urgent-mental-health-help\">UK urgent-support guide</a>.</li>\n</ul>\n<h3>Make the first conversation easier</h3>\n<p>If your mind goes blank when somebody asks “What’s wrong?”, take three notes: <strong>what changed; what daily life has become harder; what you want help with</strong>. For example: “For the last few weeks I’ve been waking early, avoiding friends and struggling to concentrate at work. I’d like help understanding it and deciding what to do.” Use your own details; this is an illustration, not a diagnostic checklist.</p>\n<p>Ask what happens next, how to contact the service while waiting and what to do if things worsen. If making contact is the obstacle, ask someone you trust to sit with you or help prepare the information. Tell the service about communication or access needs.</p>\n<h3>What does “free” mean here?</h3>\n<p>Good to Talk’s public guides are free to read without a SHIFT membership or medicine purchase. That does not mean every external service is free, immediately available or suitable for everyone. Check any provider’s costs, eligibility and waiting arrangements before agreeing to something.</p>\n<p>Use our <a href=\"/mental-health/when-someone-refuses-help\">guide to supporting someone who refuses help</a> if you are here for another person. For your own next conversation, read <a href=\"https://www.nhs.uk/mental-health/social-care-and-your-rights/how-to-access-mental-health-services/\">NHS guidance on accessing services</a>.</p>\n</section>\n<section class=\"gtt-selfhelp-panel\" id=\"self-help-v30o3\"><p class=\"eyebrow\">Practical help</p><h2>Things you can do yourself</h2><p>Bad day? Overthinking? Lost your routine? Withdrawing from people? Start with something practical — without pretending self-help replaces proper treatment.</p><p><a class=\"btn btn-primary\" href=\"/mental-health/things-you-can-do-yourself\">Show me something I can do</a></p></section><section class=\"gtt-help-panel\" id=\"proper-help-v30o4\"><p class=\"eyebrow\">When self-help isn’t enough</p><h2>Getting proper help</h2><p>GPs. NHS <a href=\"/mental-health/nhs-talking-therapies\" data-seo-context-link=\"2026-10-06\">Talking Therapies</a>. CBT. Counselling. Medication. Private therapy. Work support. What happens, what to ask and what to do if the first treatment isn’t helping.</p><p><a class=\"btn btn-primary\" href=\"/mental-health/getting-professional-help\">Show me how to get help</a></p></section><section class=\"gtt-mate-panel\" id=\"helping-mate-v30o5\">\n<p class=\"eyebrow\">For mates, partners &amp; family</p><h2>Worried about someone?</h2>\n<p>How to start the conversation, what to say, what not to say, how to ask about suicide, where to get urgent help — and how to look after yourself while supporting somebody else.</p>\n<p><a class=\"btn btn-primary\" href=\"/mental-health/helping-someone\">Help me help someone</a></p></section><h2 data-section=\"03\">Explore the full Good to Talk library</h2>\n<p>Explore guidance on life’s pressure points, practical self-help, getting professional help, supporting someone else and finding urgent support. Choose the question closest to what is happening for you.</p>\n<div class=\"gtt-next\"><h2>Keep going</h2><p><a href=\"/mens-mental-health\">Good to Talk home</a><a href=\"/mental-health/talking-about-it\">How to talk about it</a><a href=\"/mental-health/when-to-get-help\">When to get help</a></p></div>\n\n</div></details>\n  <details class=\"gt-sources\" id=\"gt-sources\"><summary>Sources and further reading <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M12 4v16M4 12h16\"/></svg></summary><div class=\"gt-reading\">\n\n<ul>\n<li><a href=\"https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/feelings-and-symptoms/\">NHS — feelings and symptoms</a></li>\n<li><a href=\"https://www.nhs.uk/every-mind-matters/mental-health-issues/\">NHS Every Mind Matters — mental health issues</a></li>\n<li><a href=\"https://www.nice.org.uk/guidance/ng222\">NICE NG222 — depression in adults: treatment and management</a></li>\n</ul>\n<p>This content is educational and is not a diagnosis.</p>\n</div></details>\n  <noscript><p class=\"gt-noscript\">The topic links and expandable guidance work without JavaScript. You can also <a href=\"#gt-more\">browse the full guidance</a>.</p></noscript>\n</details>\n</div></div>\n","client":"(()=>{'use strict';const root=document.querySelector('[data-good-to-talk-version]');if(!root)return;const $=s=>root.querySelector(s),rows=[...root.querySelectorAll('[data-gt-topic]')],input=$('#gt-search');let expanded=false;const normal=s=>s.toLowerCase().normalize('NFKD').replace(/[’']/g,'').replace(/[^a-z0-9]+/g,' ').trim();\nfunction filter(){const terms=normal(input.value).split(' ').filter(Boolean);let count=0;rows.forEach((row,i)=>{const matches=terms.length?terms.every(t=>normal(row.dataset.gtSearch+' '+row.textContent).includes(t)):expanded||i<6;row.hidden=!matches;if(matches)count++;});$('#gt-count').textContent=terms.length?count+' '+(count===1?'guide':'guides')+' matching your search':'';$('#gt-empty').hidden=count>0;$('#gt-clear').hidden=!input.value;$('#gt-all-topics').hidden=!!terms.length;$('#gt-all-topics').setAttribute('aria-expanded',String(expanded));$('#gt-all-topics').firstChild.textContent=expanded?'Show main topics ':'Browse all guides ';}\ninput.addEventListener('input',filter);$('#gt-search-form').addEventListener('submit',e=>{e.preventDefault();filter()});$('#gt-clear').addEventListener('click',()=>{input.value='';filter();input.focus()});$('#gt-all-topics').addEventListener('click',()=>{expanded=!expanded;filter()});$('#gt-reset').addEventListener('click',()=>{input.value='';expanded=true;filter();input.focus()});\nfunction openHash(){if(location.hash==='#start-here'){$('#gt-routes').scrollIntoView({block:'start'});return;}const target=document.getElementById(location.hash.slice(1));if(!target||!root.contains(target))return;let p=target;while(p&&p!==root){if(p.tagName==='DETAILS')p.open=true;p=p.parentElement;}}\naddEventListener('hashchange',openHash);filter();openHash();})();\n","images":{}},"gastric":{"path":"/comparisons/surgery/gastric-band-vs-sleeve","version":"20261021-band-sleeve-v1","template":"gastric-comparison","title":"Gastric Band or Gastric Sleeve? | SHIFT Some Timber","description":"Understand gastric band and gastric sleeve surgery. Compare procedures, eating and recovery, follow-up and questions to ask your specialist.","main":"\n<section class=\"fp-hero fg-hero\"><img class=\"fp-photo\" src=\"/comparisons/surgery/gastric-band-vs-sleeve/assets/lake-v1.webp\" width=\"1536\" height=\"1024\" alt=\"A man looking across a quiet lake towards the hills\" fetchpriority=\"high\"><div class=\"fp-shade\"></div><div class=\"fp-wrap fp-hero-copy\"><h1>Gastric band or<br>gastric sleeve?</h1><p class=\"fp-lead\">Understand the differences. Prepare for a more useful conversation with your specialist.</p><div class=\"fp-actions\"><a class=\"fp-button\" href=\"#compare-options\">Compare the options <svg class=\"fp-arrow\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M8 24h32m-11-11 11 11-11 11\"/></svg></a><a class=\"fp-button fp-outline\" href=\"#questions-to-ask\">Questions to ask</a></div></div></section>\n<div class=\"fg-cream\"><div class=\"fp-wrap fg-content\"><section id=\"compare-options\" class=\"fp-two fg-procedures\" aria-label=\"Explore each procedure\">\n<article><div class=\"fg-procedure-title\"><div><h2>Gastric band</h2><p>Explore the procedure and the questions to take to your surgical team.</p></div><svg class=\"fg-stomach\" viewBox=\"0 0 150 150\" role=\"img\" aria-label=\"Simplified illustration of a gastric band around the upper stomach\"><circle cx=\"75\" cy=\"75\" r=\"72\"/><path d=\"M68 9v23c0 9 5 14 12 17 10-7 21-4 23 9 22 9 31 40 10 64-11 12-36 15-50 7-9-5-11-12-19-8-9 4-13 17-13 24m16-3c1-7 4-13 9-13 9 0 17 16 40 12M83 10v20c0 7 3 11 8 13\"/><path class=\"fg-band\" d=\"M62 52c11 5 27 3 41-5l5 13c-13 10-31 12-44 6Z\"/><path d=\"M65 64c-11 8-6 28-18 31-12 3-18 11-19 24m33-50c-17 1-28 10-30 23\"/></svg></div>\n<details class=\"fg-detail\" id=\"band-how\"><summary><span class=\"fp-round\"><svg class=\"\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"m19 6 10 0 2 6 6 2 5 8-4 5 1 7-8 5-6-3-6 3-8-5 1-7-4-5 5-8 6-2Z\"/><circle cx=\"25\" cy=\"23\" r=\"7\"/></svg></span>How it works<svg class=\"fp-arrow\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M8 24h32m-11-11 11 11-11 11\"/></svg></summary><div class=\"fp-reading\"><p>An adjustable band sits around the upper stomach to create a smaller pouch. The stomach is not removed and the intestine is not bypassed. Adjustments are made through a port beneath the skin.</p></div></details>\n<details class=\"fg-detail\" id=\"band-discuss\"><summary><span class=\"fp-round\"><svg class=\"\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M40 25c7-16-9-26-25-19C0 12 3 30 13 34l-5 10 15-7c8 1 13-2 17-7Z\"/><path d=\"M13 17h1m9 0h1m9 0h1\"/></svg></span>What to discuss<svg class=\"fp-arrow\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M8 24h32m-11-11 11 11-11 11\"/></svg></summary><div class=\"fp-reading\"><p>Ask about band adjustments, reflux or difficulty swallowing, and the possibility of the band slipping or needing removal. Discuss the benefits, risks and expected results for your circumstances.</p></div></details>\n<details class=\"fg-detail\" id=\"band-follow-up\"><summary><span class=\"fp-round\"><svg class=\"\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><circle cx=\"24\" cy=\"12\" r=\"7\"/><circle cx=\"8\" cy=\"19\" r=\"5\"/><circle cx=\"40\" cy=\"19\" r=\"5\"/><path d=\"M12 43V33c0-9 24-9 24 0v10ZM3 38v-7c0-5 4-7 8-7m34 14v-7c0-5-4-7-8-7\"/></svg></span>Follow-up and support<svg class=\"fp-arrow\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M8 24h32m-11-11 11 11-11 11\"/></svg></summary><div class=\"fp-reading\"><p>Regular band adjustments and ongoing reviews are part of the plan. Ask who provides these, what they cost, and how your diet, supplements and blood tests will be monitored.</p></div></details>\n</article><article><div class=\"fg-procedure-title\"><div><h2>Gastric sleeve</h2><p>Explore the procedure and the questions to take to your surgical team.</p></div><svg class=\"fg-stomach\" viewBox=\"0 0 150 150\" role=\"img\" aria-label=\"Simplified illustration of a narrower sleeve shaped stomach\"><circle cx=\"75\" cy=\"75\" r=\"72\"/><path d=\"M68 9v25c0 18 24 22 23 46-1 17-12 27-26 31-19 4-29 15-30 35m15-2c2-11 11-17 27-20 32-8 34-50 17-71-9-12-11-19-11-43\"/><path class=\"fg-removed\" d=\"M89 48c30-14 48 6 45 33-3 40-27 56-54 53\"/></svg></div>\n<details class=\"fg-detail\" id=\"sleeve-how\"><summary><span class=\"fp-round\"><svg class=\"\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"m19 6 10 0 2 6 6 2 5 8-4 5 1 7-8 5-6-3-6 3-8-5 1-7-4-5 5-8 6-2Z\"/><circle cx=\"25\" cy=\"23\" r=\"7\"/></svg></span>How it works<svg class=\"fp-arrow\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M8 24h32m-11-11 11 11-11 11\"/></svg></summary><div class=\"fp-reading\"><p>Sleeve gastrectomy removes around 80% of the stomach, leaving a narrower sleeve. This permanently changes the stomach; it does not bypass the intestine.</p></div></details>\n<details class=\"fg-detail\" id=\"sleeve-discuss\"><summary><span class=\"fp-round\"><svg class=\"\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M40 25c7-16-9-26-25-19C0 12 3 30 13 34l-5 10 15-7c8 1 13-2 17-7Z\"/><path d=\"M13 17h1m9 0h1m9 0h1\"/></svg></span>What to discuss<svg class=\"fp-arrow\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M8 24h32m-11-11 11 11-11 11\"/></svg></summary><div class=\"fp-reading\"><p>Ask about the permanent change, your reflux history, and risks such as leaks, bleeding and blood clots. Your specialist can explain how your health and previous treatment affect the decision.</p></div></details>\n<details class=\"fg-detail\" id=\"sleeve-follow-up\"><summary><span class=\"fp-round\"><svg class=\"\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><circle cx=\"24\" cy=\"12\" r=\"7\"/><circle cx=\"8\" cy=\"19\" r=\"5\"/><circle cx=\"40\" cy=\"19\" r=\"5\"/><path d=\"M12 43V33c0-9 24-9 24 0v10ZM3 38v-7c0-5 4-7 8-7m34 14v-7c0-5-4-7-8-7\"/></svg></span>Follow-up and support<svg class=\"fp-arrow\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M8 24h32m-11-11 11 11-11 11\"/></svg></summary><div class=\"fp-reading\"><p>Long-term reviews, supplements and blood tests remain important. Ask your team how to follow the eating plan, manage symptoms and get support after the operation.</p></div></details>\n</article></section>\n<section class=\"fg-comparisons\"><h2>Compare key areas</h2><p class=\"fp-section-deck\">Use this side-by-side guide to explore how the procedures differ, and the questions you may want to ask.</p><div class=\"fg-compare-list\">\n<details class=\"fg-compare\" id=\"the-procedure\"><summary><svg class=\"\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><rect x=\"7\" y=\"4\" width=\"34\" height=\"40\" rx=\"3\"/><path d=\"M14 14h2m6 0h12M14 24h2m6 0h12M14 34h2m6 0h12\"/></svg><span><strong>The procedure</strong><small>An overview of how each option works.</small></span><span class=\"fg-read\">Read the comparison <svg class=\"fp-arrow\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M8 24h32m-11-11 11 11-11 11\"/></svg></span></summary><div class=\"fg-compare-body fp-two\"><div><h3>Gastric band</h3><p>An adjustable band creates a small pouch without removing the stomach. It can be removed with another operation. Ask about adjustment visits and the possibility of further surgery.</p></div><div><h3>Gastric sleeve</h3><p>Part of the stomach is removed permanently. Ask how your existing health, including reflux, affects the choice, and what risks and results your surgical team expects.</p></div></div></details>\n<details class=\"fg-compare\" id=\"eating-and-recovery\"><summary><svg class=\"\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M9 5v14c0 8 12 8 12 0V5m-6 0v39M37 44V5c-10 2-13 23 0 23\"/></svg><span><strong>Eating and recovery</strong><small>What to discuss in the early stages and beyond.</small></span><span class=\"fg-read\">Read the comparison <svg class=\"fp-arrow\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M8 24h32m-11-11 11 11-11 11\"/></svg></span></summary><div class=\"fg-compare-body fp-two\"><div><h3>Gastric band</h3><p>You will follow a staged eating plan and need to eat slowly and chew well. Band adjustments are based on food intake and progress; follow your own team’s instructions.</p></div><div><h3>Gastric sleeve</h3><p>You will also follow a staged eating plan, with guidance on portions, drinks and supplements. Your team will advise when to move between stages and build up activity.</p></div></div></details>\n<details class=\"fg-compare\" id=\"ongoing-follow-up\"><summary><svg class=\"\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><rect x=\"5\" y=\"10\" width=\"38\" height=\"33\" rx=\"3\"/><path d=\"M5 21h38M15 4v12M33 4v12\"/></svg><span><strong>Ongoing follow-up</strong><small>Support and long-term considerations.</small></span><span class=\"fg-read\">Read the comparison <svg class=\"fp-arrow\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M8 24h32m-11-11 11 11-11 11\"/></svg></span></summary><div class=\"fg-compare-body fp-two\"><div><h3>Gastric band</h3><p>Plan for band adjustments as well as long-term reviews. Ask who you can contact if you develop reflux, swallowing problems or repeated vomiting.</p></div><div><h3>Gastric sleeve</h3><p>Plan for lifelong follow-up, including nutritional monitoring and supplements as advised. Ask what support is available if reflux, eating difficulties or weight regain develop.</p></div></div></details>\n</div></section>\n<details class=\"fp-disclosure fg-questions\" id=\"questions-to-ask\"><summary>Questions to take to your specialist <svg class=\"fp-arrow\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M8 24h32m-11-11 11 11-11 11\"/></svg></summary><div class=\"fp-reading\"><ul><li>Why might this procedure fit my health and circumstances?</li><li>How does my reflux or previous surgery affect the choice?</li><li>What benefits, risks and limitations should I expect?</li><li>Who provides aftercare, adjustments, supplements and blood tests?</li><li>What is included in the cost, and what might cost extra?</li><li>Who should I contact if I develop symptoms after surgery?</li></ul><p>Ask for a written aftercare plan and time to consider your options.</p></div></details>\n<details class=\"fp-disclosure fg-sources\"><summary>About this guide and its sources <svg class=\"fp-arrow\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M8 24h32m-11-11 11 11-11 11\"/></svg></summary><div class=\"fp-reading\"><p>Written and researched by <a href=\"/authors/matt-obrien\">Matt O’Brien</a>, founder of SHIFT Some Timber. This guide supports a conversation with a qualified specialist; it does not decide whether surgery is suitable for you.</p><p>Procedure, complication and aftercare information checked against NHS guidance on 21 October 2026. Follow the individual plan given by your surgical team.</p><ul><li><a href=\"https://www.nhs.uk/tests-and-treatments/weight-loss-surgery/how-its-done/\">NHS: how weight loss surgery is done</a></li><li><a href=\"https://www.nhs.uk/tests-and-treatments/weight-loss-surgery/complications/\">NHS: possible complications</a></li><li><a href=\"https://www.nhs.uk/tests-and-treatments/weight-loss-surgery/recovering/\">NHS: recovery and follow-up</a></li></ul><p><a href=\"/editorial-standards\">Editorial standards</a> · <a href=\"/clinical-governance\">Clinical governance</a></p></div></details>\n</div></div>\n<section class=\"fp-hero fg-support\"><img class=\"fp-photo\" src=\"/comparisons/surgery/gastric-band-vs-sleeve/assets/path-v1.webp\" width=\"1536\" height=\"1024\" alt=\"A stone path winding through gentle British hills\" loading=\"lazy\"><div class=\"fp-shade\"></div><div class=\"fp-wrap fp-hero-copy\"><h2>Support for the everyday changes</h2><p>Free My Timber brings together practical tools for food, movement, check-ins and progress, alongside the advice from your clinical team.</p><a class=\"fp-button\" href=\"/join-my-timber\">Explore free My Timber <svg class=\"fp-arrow\" aria-hidden=\"true\" viewBox=\"0 0 48 48\"><path d=\"M8 24h32m-11-11 11 11-11 11\"/></svg></a></div></section>\n","client":"function openHash(){const target=document.getElementById(location.hash.slice(1));if(!target)return;let node=target;while(node){if(node.tagName==='DETAILS')node.open=true;node=node.parentElement;}}addEventListener('hashchange',openHash);openHash();","images":{"lake-v1.webp":"","path-v1.webp":""}}};
